from produire import produire,paras,steps,table
from medicaments import azithromycine
parts=[
('La {conjonctivite bactérienne aiguë} est une infection bactérienne de la conjonctive. Elle peut donner rougeur et sécrétions mucopurulentes. Le diagnostic ne repose pas sur l’écoulement seul.',paras('La forme simple doit être séparée des infections hyperpurulentes, néonatales ou associées à une atteinte cornéenne. Une kératite bactérienne relève d’un autre degré d’urgence et d’un traitement spécifique.', 'Une conjonctivite à chlamydia peut évoluer plus longtemps et nécessite un bilan particulier. Le trachome et l’infection génitale avec atteinte oculaire ne sont pas interchangeables.')),
('Le {contexte dépend de l’âge et du terrain}. Les bactéries sont une cause importante de conjonctivite chez l’enfant. Lentilles, chirurgie et immunosuppression augmentent les risques.',paras('Des staphylocoques, streptocoques ou Haemophilus peuvent être impliqués selon le contexte. L’examen ne permet pas de choisir le germe uniquement sur la teinte de la sécrétion.', 'Les formes peu sévères peuvent se résoudre sans antibiotique. Cela ne s’applique pas automatiquement au nouveau-né, à une infection gonococcique ou à une atteinte cornéenne.')),
('Le {mécanisme est une infection de surface}. L’inflammation entraîne hyperémie et sécrétions. Certains agents ou terrains exposent à une progression plus rapide.',paras('Le film lacrymal, le clignement et la surface épithéliale participent à la protection. Leur altération ou des lentilles contaminées peut favoriser l’infection.', 'La conjonctive et la cornée sont des structures différentes. Une douleur importante ou une baisse visuelle doit faire rechercher une extension ou un autre diagnostic, même si du pus est présent.')),
('Le {tri exclut les formes menaçantes}. Sécrétions hyperpurulentes, douleur, photophobie ou baisse visuelle nécessitent un avis urgent. Un nouveau-né avec œil rouge et collé ne suit pas le parcours banal.',paras('Rechercher kératite, infection gonococcique, herpès et complications postopératoires. Un porteur de lentilles doit être évalué rapidement selon le parcours suisse, avec retrait des lentilles.', 'Fièvre, proptose, douleur aux mouvements ou limitation oculomotrice font envisager une atteinte orbitaire. Ne pas attendre trois jours d’un collyre si l’un de ces signes est présent.')),
('L’{anamnèse recherche exposition et évolution}. Demander début, latéralité, quantité de sécrétions et paupières collées au réveil. Préciser vision, douleur et traitements antérieurs.',paras('Noter âge, lentilles, chirurgie, traumatisme, immunosuppression et récidives. Des symptômes urogénitaux ou une évolution prolongée orientent vers un bilan d’infection sexuellement transmissible.', 'Chez le nourrisson, rechercher contexte périnatal et signes généraux. Une infection oculaire peut accompagner une infection systémique ; la forme locale ne doit pas être évaluée isolément.')),
('L’{examen compare vision, cornée et conjonctive}. Observer les sécrétions sans leur attribuer une valeur absolue. Examiner paupières, pupilles et mouvements selon le contexte.',paras('Documenter l’acuité visuelle de chaque œil. Une vision qui reste altérée après nettoyage des sécrétions est un signal d’alarme.', 'La fluorescéine et la lampe à fente recherchent une atteinte cornéenne. Une rougeur importante avec infiltrat, ulcère ou hypopion exige l’ophtalmologue, pas simplement une ordonnance de conjonctivite.')),
('L’{approche syndromique confronte infection et diagnostics concurrents}. Les sécrétions orientent mais ne tranchent pas. Terrain et gravité déterminent la suite.',table(['Présentation','Interprétation'],[['Sécrétions et paupières collées sans alarme.','Forme bactérienne simple possible.'],['Larmoiement et contage respiratoire.','Forme virale possible ; chevauchement clinique.'],['Hyperpurulence marquée.','Gonocoque notamment à rechercher en urgence.'],['Prurit bilatéral et rhinite.','Allergie possible.'],['Douleur ou baisse visuelle.','Kératite, uvéite ou autre urgence à exclure.']])) ,
('Le {diagnostic est clinique dans une forme simple}. Aucun symptôme unique ne distingue sûrement bactérie et virus. La réévaluation doit rester prévue.',paras('Une amélioration sous antibiotique ne prouve pas rétrospectivement l’agent, car une résolution spontanée est possible. Un échec impose de revoir diagnostic, observance, résistance et atteinte cornéenne.', 'Les infections gonococciques ou à chlamydia et les formes néonatales nécessitent une démarche microbiologique et thérapeutique spécifique.')),
('Les {prélèvements sont réservés aux situations pertinentes}. Forme sévère, atypique, persistante ou suspicion d’infection transmissible peut justifier une culture ou une PCR. Une atteinte cornéenne demande la filière spécialisée.',paras('Organiser prélèvements oculaires et génitaux selon hypothèse et protocole, sans oublier les partenaires lorsque le diagnostic le justifie. Le traitement systémique est décidé par l’équipe compétente.', 'En cas de kératite sous lentilles, contacter l’ophtalmologue pour le calendrier des prélèvements et du traitement. Éviter une prescription empirique qui retarderait l’examen ou compromettrait la documentation ; apporter lentilles et étui.')),
('L’{algorithme sépare forme simple et urgence}. Le choix d’antibiotique intervient après le tri. Le contrôle de l’évolution est indispensable.',steps('Évaluer âge, vision, douleur, cornée et terrain.', 'Si nouveau-né, hyperpurulence, lentilles ou signe d’alarme, organiser l’évaluation spécialisée adaptée.', 'Si forme simple, proposer hygiène et discuter observation ou antibiotique selon contexte.', 'Si antibiotique indiqué, respecter spécialité, indication, dose et durée suisses.', 'Réévaluer rapidement en cas d’aggravation ou de réponse insuffisante.')),
('La {prise en charge suisse adapte l’antibiotique à l’indication}. HUG recommande plus largement un traitement chez l’enfant. NICE permet une stratégie différée dans certaines formes simples.',paras('Ces approches ne justifient ni antibiotique systématique de toute rougeur ni attente dans une forme à risque. Informer sur évolution spontanée possible, bénéfice attendu et effets indésirables.', '@@MEDICAMENTS@@', 'La dose Azyter de conjonctivite n’est pas une dose de kératite ni un remplacement du traitement systémique d’une infection gonococcique ou néonatale indiquée. Une association antibiotique-corticoïde n’est pas prescrite par réflexe.', 'Nettoyage doux des sécrétions et mains propres accompagnent la prise en charge. Si le diagnostic ou le matériel d’examen est insuffisant, demander l’avis spécialisé.')),
('La {prévention et le suivi} limitent contamination et retard diagnostique. Ne pas partager linge, collyres ni lentilles. Expliquer les critères de retour avant la sortie.',paras('HUG demande une réévaluation si absence de réponse à quarante-huit heures ; la notice Azyter demande de reconsidérer le diagnostic si absence d’amélioration après trois jours. Toute aggravation ou baisse visuelle demande un avis plus tôt.', 'Ne pas prolonger de soi-même la durée d’Azyter parce que la rougeur persiste. Les modalités de retour à l’école ou au travail suivent le contexte local et la transmissibilité, pas une promesse de disparition immédiate après la première goutte.')),
('Le {point clé} est de ne pas confondre pus et indication automatique. Une forme simple peut évoluer favorablement sans antibiotique. Une forme cornéenne, hyperpurulente ou néonatale ne doit pas attendre ce raisonnement de faible risque.',paras('L’âge, la vision, la cornée et le contexte guident la décision. La bonne durée d’un produit ne corrige pas une erreur de diagnostic.'))]
quiz=[('Le pus prouve-t-il seul l’origine bactérienne ?','Non.'),('Toutes les formes simples nécessitent-elles immédiatement un antibiotique ?','Non, la décision dépend du contexte et des recommandations locales.'),('Le nouveau-né suit-il le parcours simple ?','Non, évaluation urgente.'),('Que rechercher devant une hyperpurulence ?','Notamment une infection gonococcique.'),('Pourquoi mesurer la vision ?','Pour repérer une atteinte plus profonde ou menaçante.'),('Une douleur importante est-elle rassurante avec du pus ?','Non.'),('Quand envisager un prélèvement ?','Forme sévère, atypique, persistante ou agent spécifique suspecté.'),('Faut-il jeter lentilles et étui avant l’avis ?','Non, ils peuvent être utiles à l’analyse.'),('Quel est le schéma adulte exact d’Azyter ?','Une goutte deux fois par jour pendant trois jours, selon sa notice et son indication.'),('Prolonger Azyter jusqu’à disparition de toute rougeur ?','Non.'),('Le collyre remplace-t-il un traitement systémique indiqué ?','Non.'),('Le schéma de conjonctivite traite-t-il automatiquement une kératite ?','Non.'),('Une association avec corticoïde est-elle un choix de routine ?','Non.'),('Une aggravation attend-elle le contrôle prévu ?','Non, réévaluer sans délai.')]
produire(2,parts,quiz,(1,2,3,4,7),azithromycine)
